function squashMerge(owner, repo, number) {
    var last = null;
    for (var attempt = 1; attempt <= 2; attempt++) {
        try {
            var res = parseMcp(github_merge_pr({
                workspace: owner, repository: repo,
                pullRequestId: number, mergeMethod: 'squash'
