/**
 * gh-990 (2nd live instance, dart #424/#419 2026-10-17): the false-positive
 * refinement of the escalation. When the no-op budget is exhausted on a
 * head that has NOTHING to rework (unresolvedThreads === 0 — the operator
 * already addressed every thread, which is why the legs no-op'd) and the
 * head carries NO red validation (headRed === false — no validation_failed
 * park, no failing head check), parking the PR (label + 🛑 comment) is a
 * false positive: it wedges the validate-armed FIFO behind a human-owned
 * PR while the correct move is to let validation re-flow. Supression
 * requires POSITIVE evidence of BOTH sides — an unknown census (-1) or an
 * unreadable/unknown red probe (null) keeps the legacy escalation.
 */
function escalationIsFalsePositive(state) {
   var s = state || {};
   return s.unresolvedThreads === 0 && s.headRed === false;
}
