 * false positive: it wedges the validate-armed FIFO behind a human-owned
 * PR while the correct move is to let validation re-flow. Supression
 * requires POSITIVE evidence of BOTH sides — an unknown census (-1) or an
 * unreadable/unknown red probe (null) keeps the legacy escalation.
 */
function escalationIsFalsePositive(state) {
   var s = state || {};
   return s.unresolvedThreads === 0 && s.headRed === false;
