            var concl = latest[names[i]].concl;
            if (concl === 'FAILURE' || concl === 'TIMED_OUT') return true;
        }
        return false;
    } catch (eRed) {
        console.warn('  ⚠️ gh-990: head red probe failed (fail closed): ' + (eRed.message || eRed));
        return true;
    }
}

